import { Plugin } from "@opencode/plugin"
import { Limits } from "./rpc.ts"
import { fetchUsage } from "./server/api.ts"
import { createCredentials } from "./server/auth.ts"
import { log } from "./server/log.ts"
import { EVENT_TYPES } from "./server/service/events.ts"
import { createLimitsService } from "./server/service/service.ts"
import { createUpdater } from "./server/updater.ts"

type RpcEventName = "changed" | "updated" | "prefsChanged"
type EmitEvent = (name: RpcEventName, data: unknown) => Promise<void>

export default Plugin.define({
  id: "opencode-limits-go",
  async setup(ctx) {
    let emitEvent: EmitEvent = async () => {}
    const updater = createUpdater({
      onInstalled: (version) => {
        void emitEvent("updated", { version }).catch(() => {})
      },
    })
    const service = createLimitsService({
      storage: {
        get: (key) => ctx.storage.get(key),
        set: (key, value) => ctx.storage.set(key, value as never),
        remove: (key) => ctx.storage.remove(key),
      },
      credentials: createCredentials({
        integration: ctx.integration,
        provider: ctx.provider,
        options: ctx.options,
      }),
      fetchUsage,
      log,
      options: ctx.options,
      updater,
      emit: (name, data) => emitEvent(name, data),
    })
    await service.init()

    const registration = await ctx.rpc.register(Limits, {
      status: (input, call) => service.status(input, { signal: call.signal }),
      getPrefs: () => service.getPrefs(),
      setPrefs: (input) => service.setPrefs(input),
      updateStatus: (input) => service.updateStatus(input),
      installUpdate: () => service.installUpdate(),
      setUpdateConfig: (input) => service.setUpdateConfig(input),
      diagnostics: () => service.diagnostics(),
    })
    emitEvent = (name, data) => registration.events.emit(name as never, data as never)

    const stopEvents = service.subscribe(
      ctx.event.subscribe({ types: EVENT_TYPES, signal: service.signal }) as AsyncIterable<unknown>,
    )

    return async () => {
      stopEvents()
      await service.dispose()
    }
  },
})

import type { Locale } from "../core/types.ts"
import { en } from "./en.ts"
import { ru } from "./ru.ts"
import type { MessageKey, Messages } from "./keys.ts"

export { MESSAGE_KEYS } from "./keys.ts"
export type { MessageKey, Messages } from "./keys.ts"
export { en } from "./en.ts"
export { ru } from "./ru.ts"

export const DICTIONARIES: Record<Locale, Messages> = { en, ru }

export function interpolate(template: string, vars?: Record<string, string | number>): string {
  if (!vars) return template
  return template.replace(/\{\{(\w+)\}\}/g, (_, name: string) => String(vars[name] ?? ""))
}

export function message(lang: Locale, key: MessageKey, vars?: Record<string, string | number>): string {
  const dictionary = DICTIONARIES[lang] ?? en
  return interpolate(dictionary[key] ?? en[key] ?? key, vars)
}

import { execFile } from "node:child_process"
import os from "node:os"
import { promisify } from "node:util"

const exec = promisify(execFile)

export async function defaultRunCli(): Promise<unknown> {
  const win = process.platform === "win32"
  const command = win ? "cmd.exe" : "sh"
  const args = win ? ["/d", "/c", "opencode auth export"] : ["-c", "opencode auth export"]
  const { stdout } = await exec(command, args, {
    // 8s keeps credential discovery inside the status deadline.
    timeout: 8_000,
    windowsHide: true,
    maxBuffer: 4 * 1024 * 1024,
    // cmd.exe searches the current directory before PATH: never let a repo-provided opencode.cmd run.
    cwd: os.homedir(),
    env: win ? { ...process.env, NoDefaultCurrentDirectoryInExePath: "1" } : process.env,
  })
  // JSON.parse errors can quote a fragment of stdout containing tokens: do not rethrow the original error.
  try {
    return JSON.parse(stdout)
  } catch {
    throw new Error("opencode auth export did not return JSON")
  }
}
